update private.memory_private_media_policy set enabled=true,approved=true,paused=false,revision='ELIGIBILITY_LOCAL',observed_at=now(),quota_bytes=50000000,physical_bytes=100000000,preparations_per_day=100,decode_attempts_per_day=100,upload_max_in_flight=10;
select set_config('request.jwt.claim.sub','77777777-7777-4777-8777-777777777777',false);
create function pg_temp.reserve() returns jsonb language sql as $$select public.reserve_memory_private_image('77777777-7777-4777-8777-777777777777','77777777-7777-4777-8777-777777777952',1,'77777777-7777-4777-8777-777777777953','ELIGIBILITY_LOCAL',repeat('b',64),repeat('c',64),repeat('d',64),800,200,10,10)$$;
set role authenticated;
select pg_temp.fails($q$select public.authorize_memory_private_image_attempt('77777777-7777-4777-8777-777777777952',1,'ELIGIBILITY_LOCAL')$q$,'ELIGIBILITY_REQUIRED','revoked owner denied before decode');
set role service_role;
select pg_temp.fails('select pg_temp.reserve()','ELIGIBILITY_REQUIRED','service reservation checks actual owner eligibility');
reset role;
select pg_temp.ok(not exists(select 1 from private.memory_private_media where owner_id='77777777-7777-4777-8777-777777777777'),'denied reservation creates no quota row');
update private.memory_eligibility_evidence set state='GRANTED',revision=revision+1;
set role service_role;
select set_config('test.image.id',pg_temp.reserve()->>'id',false);
reset role;
update private.memory_eligibility_evidence set state='REVOKED',revision=revision+1;
set role service_role;
select pg_temp.fails($q$select public.complete_memory_private_image(current_setting('test.image.id')::uuid)$q$,'ELIGIBILITY_REQUIRED','revocation between reserve and complete prevents READY');
reset role;
select pg_temp.ok((select state='PREPARING' and main_bytes+thumb_bytes=1000 from private.memory_private_media where id=current_setting('test.image.id')::uuid),'failed completion preserves reservation and quota');
set role authenticated;
select public.cancel_memory_private_image('77777777-7777-4777-8777-777777777953');
select public.cancel_memory_private_image('77777777-7777-4777-8777-777777777953');
reset role;
select pg_temp.ok((select state='DELETING' and main_bytes+thumb_bytes=1000 from private.memory_private_media where id=current_setting('test.image.id')::uuid),'revoked cancellation remains idempotent and retains quota');
set role service_role;
select public.complete_memory_private_image_cleanup(current_setting('test.image.id')::uuid);
reset role;
select pg_temp.ok((select state='DELETING' from private.memory_private_media where id=current_setting('test.image.id')::uuid),'cleanup cannot settle before write grace expires');
update private.memory_private_media set cleanup_after=now()-interval '1 second' where id=current_setting('test.image.id')::uuid;
set role service_role;
select public.complete_memory_private_image_cleanup(current_setting('test.image.id')::uuid);
select pg_temp.fails($q$select public.complete_memory_private_image_without_eligibility(current_setting('test.image.id')::uuid)$q$,'permission denied','service cannot bypass completion wrapper');
reset role;
select pg_temp.ok((select state='DELETED' from private.memory_private_media where id=current_setting('test.image.id')::uuid),'cleanup finalizes retired manifest without eligibility');
select pg_temp.ok((select coalesce(sum(main_bytes+thumb_bytes),0)=0 from private.memory_private_media where owner_id='77777777-7777-4777-8777-777777777777' and state<>'DELETED'),'final cleanup releases counted quota');
update private.memory_eligibility_evidence set state='GRANTED',revision=revision+1;
set role service_role;
select set_config('test.ready.id',public.reserve_memory_private_image('77777777-7777-4777-8777-777777777777','77777777-7777-4777-8777-777777777952',1,'77777777-7777-4777-8777-777777777954','ELIGIBILITY_LOCAL',repeat('b',64),repeat('c',64),repeat('d',64),800,200,10,10)->>'id',false);
select public.complete_memory_private_image(current_setting('test.ready.id')::uuid);
reset role;
select pg_temp.ok((select state='READY' from private.memory_private_media where id=current_setting('test.ready.id')::uuid),'eligible owner can finalize representation');
update private.memory_eligibility_evidence set state='REVOKED',revision=revision+1;
set role authenticated;
select pg_temp.ok(public.get_memory_private_image_policy('77777777-7777-4777-8777-777777777952',1)->'representation'->>'id'=current_setting('test.ready.id'),'revoked owner recovers completed receipt through existing policy read');
select pg_temp.ok(public.read_memory_private_image('77777777-7777-4777-8777-777777777952',1,'main',false)->>'id'=current_setting('test.ready.id'),'owner read resolver remains available after write eligibility revocation');
select public.cancel_memory_private_image('77777777-7777-4777-8777-777777777954');
reset role;
select pg_temp.ok((select state='DELETING' from private.memory_private_media where id=current_setting('test.ready.id')::uuid),'revoked owner can retire READY representation');
